#!/usr/bin/env node
// Writes packages/core/src/skills-builtin.generated.ts from
// packages/core/skills/builtin/<name>/SKILL.md, so that the built-in skills are
// TS strings in Workers (no file system there). Run after a SKILL.md change:
//   node packages/core/scripts/gen-skills.mjs
// test/skills.test.ts fails when the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

export function render() {
  const dir = join(root, "skills", "builtin");
  const names = readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
    .sort();
  let out = "// Generated by packages/core/scripts/gen-skills.mjs from packages/core/skills/builtin. Do not edit.\n\n";
  out += "/** The SKILL.md files of the built-in skills, keyed by directory name. */\n";
  out += "export const BUILTIN_SKILL_FILES: Readonly<Record<string, string>> = {\n";
  for (const n of names) {
    const content = readFileSync(join(dir, n, "SKILL.md"), "utf8");
    out += `  ${JSON.stringify(n)}: ${JSON.stringify(content)},\n`;
  }
  out += "};\n";
  return out;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(root, "src", "skills-builtin.generated.ts"), render());
}
